Here is a complete, single-file web application built with HTML, Tailwind CSS, and Vanilla JavaScript. 

It tracks the 20 seats, prevents duplicate emails, persists registrations in the browser using `localStorage`, and includes an admin toggle to clear the seats for testing.

Save the code below as an `index.html` file and open it in any browser:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Workshop Registration</title>
  <script src="https://cdn.tailwindcss.com"></script>
</head>
<body class="bg-gray-50 text-gray-800 min-h-screen py-10 px-4">

  <div class="max-w-xl mx-auto space-y-6">

    <!-- Header Card -->
    <div class="bg-white p-6 rounded-xl shadow-sm border border-gray-100 text-center">
      <h1 class="text-3xl font-bold text-gray-900">Hands-on Web Workshop</h1>
      <p class="text-gray-500 mt-2">Reserve your spot. Limited to 20 seats only!</p>

      <!-- Seat Counter -->
      <div class="mt-6">
        <div class="flex justify-between items-center mb-2">
          <span class="text-sm font-medium text-gray-600">Capacity</span>
          <span id="seatCountText" class="text-sm font-bold text-indigo-600">20 / 20 seats available</span>
        </div>
        <div class="w-full bg-gray-200 rounded-full h-3 overflow-hidden">
          <div id="progressBar" class="bg-indigo-600 h-3 transition-all duration-300" style="width: 0%"></div>
        </div>
      </div>
    </div>

    <!-- Registration Form -->
    <div class="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
      <form id="regForm" class="space-y-4">
        <div>
          <label for="name" class="block text-sm font-medium text-gray-700">Full Name</label>
          <input type="text" id="name" required placeholder="Jane Doe" 
            class="mt-1 block w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500">
        </div>

        <div>
          <label for="email" class="block text-sm font-medium text-gray-700">Email Address</label>
          <input type="email" id="email" required placeholder="jane@example.com" 
            class="mt-1 block w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500">
        </div>

        <button type="submit" id="submitBtn" 
          class="w-full bg-indigo-600 text-white font-medium py-2.5 px-4 rounded-lg hover:bg-indigo-700 transition duration-150 disabled:bg-gray-400 disabled:cursor-not-allowed">
          Claim Your Seat
        </button>

        <p id="message" class="text-center text-sm font-medium hidden"></p>
      </form>
    </div>

    <!-- Attendee List -->
    <div class="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
      <div class="flex justify-between items-center mb-4">
        <h2 class="text-lg font-semibold text-gray-900">Registered Attendees</h2>
        <button id="resetBtn" class="text-xs text-red-500 hover:underline">Reset All (Demo)</button>
      </div>
      <ul id="attendeeList" class="divide-y divide-gray-100 text-sm">
        <!-- Javascript populates this -->
      </ul>
    </div>

  </div>

  <script>
    const TOTAL_SEATS = 20;

    // Elements
    const form = document.getElementById('regForm');
    const nameInput = document.getElementById('name');
    const emailInput = document.getElementById('email');
    const submitBtn = document.getElementById('submitBtn');
    const message = document.getElementById('message');
    const seatCountText = document.getElementById('seatCountText');
    const progressBar = document.getElementById('progressBar');
    const attendeeList = document.getElementById('attendeeList');
    const resetBtn = document.getElementById('resetBtn');

    // Load saved attendees or start empty
    let attendees = JSON.parse(localStorage.getItem('workshop_attendees')) || [];

    function updateUI() {
      const taken = attendees.length;
      const available = TOTAL_SEATS - taken;

      // Update text and progress bar
      seatCountText.textContent = `${available} / ${TOTAL_SEATS} seats available`;
      const percentage = (taken / TOTAL_SEATS) * 100;
      progressBar.style.width = `${percentage}%`;

      // Check if workshop is full
      if (taken >= TOTAL_SEATS) {
        submitBtn.disabled = true;
        submitBtn.textContent = 'Workshop Sold Out';
        nameInput.disabled = true;
        emailInput.disabled = true;
      } else {
        submitBtn.disabled = false;
        submitBtn.textContent = 'Claim Your Seat';
        nameInput.disabled = false;
        emailInput.disabled = false;
      }

      // Render attendees list
      attendeeList.innerHTML = '';
      if (attendees.length === 0) {
        attendeeList.innerHTML = `<li class="py-2 text-gray-400 italic">No registrations yet. Be the first!</li>`;
      } else {
        attendees.forEach((attendee, index) => {
          const li = document.createElement('li');
          li.className = 'py-2 flex justify-between items-center';
          li.innerHTML = `
            <div>
              <span class="font-medium text-gray-800">${index + 1}. ${escapeHTML(attendee.name)}</span>
              <span class="text-xs text-gray-400 block">${escapeHTML(attendee.email)}</span>
            </div>
            <span class="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded-full font-medium">Confirmed</span>
          `;
          attendeeList.appendChild(li);
        });
      }
    }

    function showMessage(text, isError = false) {
      message.textContent = text;
      message.className = `text-center text-sm font-medium ${isError ? 'text-red-500' : 'text-green-600'}`;
      message.classList.remove('hidden');
    }

    function escapeHTML(str) {
      return str.replace(/[&<>'"]/g, 
        tag => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[tag] || tag)
      );
    }

    // Form submission
    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const name = nameInput.value.trim();
      const email = emailInput.value.trim().toLowerCase();

      if (attendees.length >= TOTAL_SEATS) {
        showMessage('Sorry, no seats left!', true);
        return;
      }

      // Check for duplicate email
      const alreadyRegistered = attendees.some(a => a.email.toLowerCase() === email);
      if (alreadyRegistered) {
        showMessage('This email address has already claimed a seat.', true);
        return;
      }

      // Save attendee
      attendees.push({ name, email });
      localStorage.setItem('workshop_attendees', JSON.stringify(attendees));

      // Reset form & UI
      nameInput.value = '';
      emailInput.value = '';
      showMessage('🎉 Seat reserved successfully!', false);
      updateUI();
    });

    // Reset button (for demo / testing purposes)
    resetBtn.addEventListener('click', () => {
      if (confirm('Are you sure you want to clear all registrations?')) {
        attendees = [];
        localStorage.removeItem('workshop_attendees');
        message.classList.add('hidden');
        updateUI();
      }
    });

    // Initial render
    updateUI();
  </script>
</body>
</html>
```

### Features included:
1. **Capacity Limit**: Automatically disables the form and updates the button when all 20 seats are claimed.
2. **Duplicate Prevention**: Rejects submissions if an email has already claimed a seat.
3. **Data Persistence**: Uses the browser's `localStorage` so data stays even if you refresh the page.
4. **Visual Progress**: A progress bar and dynamic counter display the remaining capacity.
5. **Reset Button**: Includes a small admin option to clear the data so you can test it repeatedly.

